const CACHE='mecomunico-v0.2.2';
const ASSETS=['./','./index.html','./app.html','./activities.js','./voice.js','./install.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png','./apple-touch-icon.png'];
// Reconstruct redirected responses before caching: some hosts canonicalize app.html to /app.
function cacheable(r){return new Response(r.clone().body,{status:r.status,statusText:r.statusText,headers:r.headers})}
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CACHE);for(const path of ASSETS){const r=await fetch(new Request(new URL(path,self.registration.scope),{cache:'reload',redirect:'follow'}));if(!r.ok)throw Error('Asset unavailable '+path);await c.put(new URL(path,self.registration.scope),cacheable(r))}await self.skipWaiting()})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const key of await caches.keys())if((key.startsWith('mecomunico-')||key.startsWith('paso-a-paso-'))&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin)return;const scope=new URL(self.registration.scope);const rel=url.pathname.slice(scope.pathname.length);if(e.request.mode==='navigate'){const file=/^app(?:\.html)?\/?$/.test(rel)?'./app.html':(rel===''||rel==='index.html'?'./index.html':null);if(!file)return;e.respondWith((async()=>{const c=await caches.open(CACHE),key=new URL(file,scope);try{const r=await fetch(e.request);if(!r.ok)throw Error('Navigation failed');const clean=cacheable(r);await c.put(key,clean.clone());return clean}catch{const hit=await c.match(key);return hit||new Response('Sin conexión. Abre MeComunico una vez con internet.',{status:503,headers:{'Content-Type':'text/plain;charset=utf-8'}})}})());return}if(!ASSETS.some(x=>new URL(x,scope).pathname===url.pathname))return;e.respondWith((async()=>{const c=await caches.open(CACHE);const hit=await c.match(e.request,{ignoreSearch:true});if(hit)return hit;return fetch(e.request)})())});
